 "gram-461": {"promptNative":"Je suis étudiant. (particule de thème)","explain":"« は » marque le thème (« en cuanto a mí… »).","wrongNote":"« は » marque le thème (« en cuanto a mí… »).","distractorNotes":{"が (ga)":"marque le sujet / une information nouvelle","を (wo)":"marque le complément d’objet direct","に (ni)":"marque une destination ou un temps"}},
 "gram-462": {"promptNative":"Je mange une pomme. (particule d’objet)","explain":"« を » marque le complément d’objet direct — ce qui est mangé.","wrongNote":"« を » marque le complément d’objet direct — ce qui est mangé.","distractorNotes":{"は (wa)":"marque le thème","が (ga)":"marque le sujet","で (de)":"marque le lieu ou le moyen d’une action"}},
 "gram-463": {"promptNative":"Je vais à l’école. (particule de destination)","explain":"« に » marque la destination du mouvement (« a »).","wrongNote":"« に » marque la destination du mouvement (« a »).","distractorNotes":{"を (wo)":"marque le complément d’objet direct","で (de)":"marque où se déroule une action","と (to)":"signifie « con » / « y »"}},
 "gram-464": {"promptNative":"J’étudie à la bibliothèque. (particule de lieu de l’action)","explain":"« で » marque le lieu où se déroule une action.","wrongNote":"« で » marque le lieu où se déroule une action.","distractorNotes":{"に (ni)":"marque une destination ou un lieu d’existence","を (wo)":"marque le complément d’objet direct","へ (e)":"marque la direction (« hacia »)"}},
 "gram-465": {"promptNative":"Je parle avec un ami. (particule « avec »)","explain":"« と » signifie « con » (faire quelque chose ensemble).","wrongNote":"« と » signifie « con » (faire quelque chose ensemble).","distractorNotes":{"を (wo)":"marque le complément d’objet direct","に (ni)":"marque une destination ou un destinataire","で (de)":"marque le lieu ou le moyen"}},
 "gram-466": {"promptNative":"J’y vais en train. (particule de moyen)","explain":"« で » marque aussi le moyen (« en tren »).","wrongNote":"« で » marque aussi le moyen (« en tren »).","distractorNotes":{"に (ni)":"marque une destination","を (wo)":"marque le complément d’objet direct","と (to)":"signifie « con »"}},
 "gram-467": {"promptNative":"Je me lève à 7 h du matin. (particule de temps)","explain":"« に » marque une heure précise (« a las 7 »).","wrongNote":"« に » marque une heure précise (« a las 7 »).","distractorNotes":{"で (de)":"marque le lieu ou le moyen","を (wo)":"marque le complément d’objet direct","が (ga)":"marque le sujet"}},
